def longest_semi_repetitive_substring(s):
    left=0;previous_pair=0;answer=1
    for right in range(1,len(s)):
        if s[right]==s[right-1]:left=previous_pair;previous_pair=right
        answer=max(answer,right-left+1)
    return answer

